+    method: 'POST',
+    headers: { ...authHeader() },
+    body,
+    credentials: 'include',
+  });
+  if (!response.ok) {
+    const text = await response.text();
+    throw new ApiError(response.status, text, response.statusText);
+  }
+  const text = await response.text();
+  return (text ? JSON.parse(text) : {}) as T;
+}
